// FRIEREN CONTINENTAL RAILWAY NETWORK DATA v2.0
// MAGE-RAIL: Complete Mixed-Service Network
// Total stations: 359 | Total lines: 33
//
// LINE CATEGORIES:
//   highspeed  – L1–L6, L8, L10, L11   (Komet/Adler/Reiher/Seelenzug)
//   express    – L7, L12                (Falke)
//   regional   – RE1–RE8                (Regional-Klasse, 160 km/h)
//   local      – LK1–LK3, BL1–BL2      (Pendler-Klasse S-Bahn / Bergbahn)
//   freight    – FG1–FG5               (Fracht-Klasse, NO PASSENGERS)
//
// FREIGHT NOTE: Lines with freightOnly:true carry no passengers.
// Use passengerRailLines export for journey planning.
// ============================================================

export interface Station {
  id: string;
  name: { kanji: string; romaji: string; english: string; czech: string; };
  fullName: string;
  region: string;
  subRegion: string;
  x: number;
  y: number;
  importance: 'hub' | 'major' | 'regional' | 'local';
  lines: string[];
}

export interface LineSegment {
  from: string;
  to: string;
  distance: number;
  travelTime: number;
}

export interface RailLine {
  id: string;
  name: string;
  color: string;
  maxSpeed: number;
  trainSet: string;
  serviceCategory: 'highspeed' | 'express' | 'regional' | 'local' | 'freight';
  freightOnly: boolean;
  dwellMinutes: number;
  segments: LineSegment[];
  stations: string[];
}

export const TRAIN_CLASSES = {
  KOMET:    { name: 'Komet-Klasse',    speed: 360 },
  ADLER:    { name: 'Adler-Klasse',    speed: 320 },
  FALKE:    { name: 'Falke-Klasse',    speed: 300 },
  REIHER:   { name: 'Reiher-Klasse',   speed: 280 },
  SEELENZUG:{ name: 'Seelenzug',        speed: 230 },
  SCHNELL:  { name: 'Schnell-Klasse',  speed: 220 },
  REGIONAL: { name: 'Regional-Klasse', speed: 160 },
  PENDLER:  { name: 'Pendler-Klasse',  speed: 120 },
  FRACHT:   { name: 'Fracht-Klasse',   speed:  80 },
} as const;

const KOMET_SPEED     = TRAIN_CLASSES.KOMET.speed;
const ADLER_SPEED     = TRAIN_CLASSES.ADLER.speed;
const FALKE_SPEED     = TRAIN_CLASSES.FALKE.speed;
const REIHER_SPEED    = TRAIN_CLASSES.REIHER.speed;
const SEELENZUG_SPEED = TRAIN_CLASSES.SEELENZUG.speed;
// const SCHNELL_SPEED   = TRAIN_CLASSES.SCHNELL.speed;
const REGIONAL_SPEED  = TRAIN_CLASSES.REGIONAL.speed;
const PENDLER_SPEED   = TRAIN_CLASSES.PENDLER.speed;
const FRACHT_SPEED    = TRAIN_CLASSES.FRACHT.speed;
export const CRUISING_SPEED = KOMET_SPEED;

const KINEMATICS_REFERENCE_SPEED = 350;
const KINEMATICS_REFERENCE_MIN   = 10;

export function kinematicPenaltyMinutes(speed: number): number {
  return (KINEMATICS_REFERENCE_MIN * speed) / KINEMATICS_REFERENCE_SPEED;
}

export function calcTravelTime(distance: number, speed: number = CRUISING_SPEED): number {
  const kinematicPenalty = kinematicPenaltyMinutes(speed) * 2;
  return Math.round((distance / speed) * 60 + kinematicPenalty);
}

