/** Lines available for passenger journey planning (excludes freightOnly lines) */
export const passengerRailLines = railLines.filter(l => !l.freightOnly);

/** Freight-only lines (no passenger services) */
export const freightRailLines = railLines.filter(l => l.freightOnly);

// ============================================================
// SEARCH UTILITY – used by StationSearch component
// ============================================================
export function searchStations(query: string, options?: {
  limit?: number;
  regionFilter?: string;
  importanceFilter?: Station['importance'][];
  lineFilter?: string;
  excludeFreightOnly?: boolean;
}): Station[] {
  const q = query.trim().toLowerCase();
  if (!q) return [];
  const limit = options?.limit ?? 12;
  const regionFilter = options?.regionFilter?.toLowerCase();
  const importanceFilter = options?.importanceFilter;
  const lineFilter = options?.lineFilter;
  const excludeFreight = options?.excludeFreightOnly ?? false;

  return stations
    .filter(s => {
      if (regionFilter && !s.region.toLowerCase().includes(regionFilter)) return false;
      if (importanceFilter && !importanceFilter.includes(s.importance)) return false;
      if (lineFilter && !s.lines.includes(lineFilter)) return false;
      if (excludeFreight) {
        const hasPassengerLine = s.lines.some(lid => {
          const rl = railLines.find(r => r.id === lid);
          return rl && !rl.freightOnly;
        });
        if (!hasPassengerLine) return false;
      }
      return (
        s.id.toLowerCase().includes(q) ||
        s.name.english.toLowerCase().includes(q) ||
        s.name.czech.toLowerCase().includes(q) ||
        s.name.romaji.toLowerCase().includes(q) ||
        s.name.kanji.includes(query) ||
        s.fullName.toLowerCase().includes(q) ||
        s.region.toLowerCase().includes(q) ||
        s.subRegion.toLowerCase().includes(q)
      );
    })
    .sort((a, b) => {
      const importanceOrder = { hub: 0, major: 1, regional: 2, local: 3 };
      const aScore = importanceOrder[a.importance];
      const bScore = importanceOrder[b.importance];
      if (aScore !== bScore) return aScore - bScore;
      // Prioritize exact prefix matches
      const aStart = a.name.english.toLowerCase().startsWith(q) ? 0 : 1;
      const bStart = b.name.english.toLowerCase().startsWith(q) ? 0 : 1;
      return aStart - bStart;
    })
    .slice(0, limit);
}

export function getImportanceBadge(importance: Station['importance']): string {
  switch (importance) {
    case 'hub':      return '●';
    case 'major':    return '◉';
    case 'regional': return '○';
    case 'local':    return '·';
    default:         return '·';
  }
}

export function getImportanceLabel(importance: Station['importance'], lang: 'en' | 'cs' = 'en'): string {
  if (lang === 'cs') {
    switch (importance) {
      case 'hub':      return 'Hlavní uzel';
      case 'major':    return 'Velká stanice';
      case 'regional': return 'Regionální';
      case 'local':    return 'Místní zastávka';
    }
  }
  switch (importance) {
    case 'hub':      return 'Hub Terminal';
    case 'major':    return 'Major Station';
    case 'regional': return 'Regional Station';
    case 'local':    return 'Local Halt';
    default:         return 'Station';
  }
}

export function getLineCategoryLabel(cat: RailLine['serviceCategory'], lang: 'en' | 'cs' = 'en'): string {
  if (lang === 'cs') {
    const labels: Record<string, string> = {
      highspeed: 'Rychlovlak', express: 'Expresní', regional: 'Regionální',
      local: 'Místní / S-Bahn', freight: 'Nákladní (zavřeno pro cestující)',
    };
    return labels[cat] ?? cat;
  }
  const labels: Record<string, string> = {
    highspeed: 'High-Speed Rail', express: 'Express',
    regional: 'Regional', local: 'S-Bahn / Local', freight: 'Freight Only',
  };
  return labels[cat] ?? cat;
}

export type { Station as StationType };

// ============================================================
// LOOKUP HELPERS
// ============================================================
export function getStationById(id: string): Station | undefined {
  return stationMap.get(id);
}

export function getLineById(id: string): RailLine | undefined {
  return railLines.find(l => l.id === id);
}

